#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cmath>
#include <climits>
#include <iomanip>
#include <numeric>
using namespace std;

using i64 = long long;
const i64 MOD = 1000000007LL;
const i64 MOD1 = 998244353LL;
constexpr int T = 14;

i64 mod_exp(i64 base, i64 exp, i64 mod) {
    i64 result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

namespace seq_solver {
    vector<i64> berlekamp_massey(const vector<i64>& seq) {
        int n = seq.size();
        vector<i64> cur, ls;
        int lf = -1;
        i64 ld = 0;
        for (int i = 0; i < n; ++i) {
            i64 val = 0;
            for (int j = 0; j < (int)cur.size(); ++j)
                val = (val + seq[i - j - 1] * cur[j]) % MOD;
            val = (val - seq[i]) % MOD;
            if (val == 0) continue;
            if (cur.empty()) {
                cur.resize(i + 1, 0);
                lf = i;
                ld = val;
                continue;
            }
            i64 k = (-val * mod_exp(ld, MOD - 2, MOD)) % MOD;
            vector<i64> c(i - lf - 1, 0);
            c.push_back(k);
            for (size_t j = 0; j < ls.size(); ++j)
                c.push_back((-ls[j] * k) % MOD);
            if ((int)c.size() < (int)cur.size()) c.resize(cur.size());
            for (size_t j = 0; j < cur.size(); ++j)
                c[j] = (c[j] + cur[j]) % MOD;
            if ((int)cur.size() < i - lf + (int)ls.size()) {
                ls = cur;
                lf = i;
                ld = val;
            }
            cur = c;
        }
        for (auto& x : cur) x = (x % MOD + MOD) % MOD;
        return cur;
    }

    vector<i64> h_vec;
    vector<i64> a_vec;
    int m_len;

    void poly_mult(vector<i64>& p, const vector<i64>& q) {
        vector<i64> tmp(m_len * 2, 0);
        for (int i = 0; i < m_len; ++i) if (p[i])
            for (int j = 0; j < m_len; ++j)
                tmp[i + j] = (tmp[i + j] + p[i] * q[j]) % MOD;
        for (int i = m_len * 2 - 1; i >= m_len; --i) if (tmp[i])
            for (int j = m_len - 1; j >= 0; --j)
                tmp[i - j - 1] = (tmp[i - j - 1] + tmp[i] * h_vec[j]) % MOD;
        for (int i = 0; i < m_len; ++i) p[i] = tmp[i];
    }

    i64 eval(i64 K) {
        vector<i64> s(m_len, 0), t(m_len, 0);
        s[0] = 1;
        if (m_len != 1) t[1] = 1;
        else t[0] = h_vec[0];
        while (K) {
            if (K & 1) poly_mult(s, t);
            poly_mult(t, t);
            K >>= 1;
        }
        i64 res = 0;
        for (int i = 0; i < m_len; ++i)
            res = (res + s[i] * a_vec[i]) % MOD;
        return (res % MOD + MOD) % MOD;
    }

    i64 compute(const vector<i64>& seq, i64 n) {
        if (n < (i64)seq.size()) return seq[n];
        h_vec = berlekamp_massey(seq);
        m_len = h_vec.size();
        if (m_len == 0) return 0;
        a_vec = vector<i64>(seq.begin(), seq.begin() + m_len);
        return eval(n);
    }
}

i64 count_valid(i64 n, i64 upper_bound) {
    i64 cnt = 0;
    string s = to_string(n);
    int len = s.length();
    if (n > 0) cnt++;
    for (int i = 1; i < T; i++) {
        i64 base = 1, num = n;
        for (int j = 0; j + 1 < i; j++) base *= 10;
        for (int j = len; j < i; j++) num *= 10;
        if (i < len) {
            string prefix = s.substr(0, i);
            num = stoll(prefix) + 1;
        }
        if (num > upper_bound) num = upper_bound;
        if (num > base) cnt += num - base;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    i64 n;
    cin >> n;
    n++;
    i64 limit = n;

    i64 adjustment = (n % MOD) * ((n / MOD1) + 2) % MOD;
    adjustment = (MOD - adjustment) % MOD;

    i64 total = 0;
    for (i64 offset = -n / MOD1 - 1; offset <= n / MOD1 + 1; offset++) {
        i64 count = 0;
        for (int digits = 0; digits < T; digits++) {
            i64 left = 0, right = 1;
            if (digits >= 1) {
                left = 1;
                for (int k = 0; k + 1 < digits; k++) left *= 10;
                right = left * 10;
            }
            if (right > n) right = n;
            i64 last_right = right;
            if (left < right) {
                left--;
                while (right - left > 1) {
                    i64 mid = (left + right) / 2;
                    if (count_valid(mid, limit) > mid + MOD1 * offset - 1) right = mid;
                    else left = mid;
                }
                count += last_right - right;
            }
        }
        total += count;
    }

    total %= MOD;
    total = ((-total - adjustment) % MOD * MOD1) % MOD;
    total = (total % MOD + MOD) % MOD;
    cout << total << '\n';

    return 0;
}
